class Solution {
public:
    string toHex(int num) {
        if (num == 0) return "0";
        string hex = "0123456789abcdef";
        string result;
        unsigned int n = static_cast<unsigned int>(num);
        for (int i = 7; i >= 0; i--) {
            int nibble = (n >> (i * 4)) & 0xf;
            if (!result.empty() || nibble != 0) {
                result.push_back(hex[nibble]);
            }
        }
        return result;
    }
};
